INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3920700, 554185, 37252, '<td valign="top">very cool shot</td>', 'very cool shot', '2007-07-20 02:13:15.000000', NULL, 1),
(3920701, 556549, 37252, '<td valign="top">closer crop would make this even better</td>', 'closer crop would make this even better', '2007-07-20 02:13:41.000000', NULL, 1),
(3920702, 555409, 37252, '<td valign="top">needs to be sharper</td>', 'needs to be sharper', '2007-07-20 02:14:08.000000', NULL, 1),
