(3920986, 555308, 39430, '<td valign="top">I''m not sure about the border, and I don''t understand the title, but it''s a nice shot.  I like the crisp detail throughout.</td>', 'I''m not sure about the border, and I don''t understand the title, but it''s a nice shot.  I like the crisp detail throughout.', '2007-07-20 07:07:33.000000', NULL, 1),
(3920987, 556554, 39430, '<td valign="top">Nice shot!  The border is a little overdone, but I love the colours and details of the crowded umbrellas.</td>', 'Nice shot!  The border is a little overdone, but I love the colours and details of the crowded umbrellas.', '2007-07-20 07:08:20.000000', NULL, 1),
(3920989, 556561, 39430, '<td valign="top">Simple.  Clean.  I think maybe too much so.  It might not score well.</td>', 'Simple.  Clean.  I think maybe too much so.  It might not score well.', '2007-07-20 07:09:19.000000', NULL, 1),
