(3921046, 553257, 39430, '<td valign="top">The limited tone pallette detracts from the interest of this photo for me.  I''d prefer more shading and interesting lighting effects on the object and the background.  It does emphasise the clean perspective this way though.</td>', 'The limited tone pallette detracts from the interest of this photo for me.  I''d prefer more shading and interesting lighting effects on the object and the background.  It does emphasise the clean perspective this way though.', '2007-07-20 08:02:06.000000', NULL, 1),
(3921047, 555876, 39430, '<td valign="top">Nice model, and you''ve chosen a good perspective for the photo.</td>', 'Nice model, and you''ve chosen a good perspective for the photo.', '2007-07-20 08:02:44.000000', NULL, 1),
