(3921559, 555020, 45198, '<td valign="top">WOW !!! I hope you didn''t create it just for this challenge.<br/>Nice work though</td>', 'WOW !!! I hope you didn''t create it just for this challenge.Nice work though', '2007-07-20 12:29:14.000000', NULL, 1),
