INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3921682, 556412, 74605, '<td valign="top">Made me smile!  Isn'' that the way we feel sometimes.  Nice use of theme.</td>', 'Made me smile!  Isn'' that the way we feel sometimes.  Nice use of theme.', '2007-07-20 13:23:31.000000', NULL, 1),
(3921683, 556854, 74605, '<td valign="top">Cute idea1</td>', 'Cute idea1', '2007-07-20 13:23:42.000000', NULL, 1),
(3921684, 556616, 57882, '<td valign="top">Very cool! A+ for originality.</td>', 'Very cool! A+ for originality.', '2007-07-20 13:23:42.000000', NULL, 1),
(3921686, 554123, 74605, '<td valign="top">Nice scene.</td>', 'Nice scene.', '2007-07-20 13:23:56.000000', NULL, 1),
(3921688, 554919, 66253, '<td valign="top">Cute title; nice clear image.</td>', 'Cute title; nice clear image.', '2007-07-20 13:24:07.000000', NULL, 1),
