(3921698, 556848, 74605, '<td valign="top">Pretty colors.</td>', 'Pretty colors.', '2007-07-20 13:25:58.000000', NULL, 1),
(3921699, 556944, 57882, '<td valign="top">WOW!  So dynamic.  Nicely done.</td>', 'WOW!  So dynamic.  Nicely done.', '2007-07-20 13:26:05.000000', NULL, 1),
(3921700, 554551, 74605, '<td valign="top">Nice idea.  DOF is nice here.</td>', 'Nice idea.  DOF is nice here.', '2007-07-20 13:26:25.000000', NULL, 1),
(3921701, 555395, 74605, '<td valign="top">Fun photo.</td>', 'Fun photo.', '2007-07-20 13:26:45.000000', NULL, 1),
(3921703, 555763, 66253, '<td valign="top">Ooh, very artistic. I love the combination of b/w and color, and the conceit of the drawing. If I were to be a purist about things, I''d wonder about the shadows from the flower, which seem puzzling to me, maybe from different light sources? I''d also think that the stem would be in color, too.I like the ambiguity of whether it''s the sketch coming to life, or the pencil draining color from the flower.</td>', 'Ooh, very artistic. I love the combination of b/w and color, and the conceit of the drawing. If I were to be a purist about things, I''d wonder about the shadows from the flower, which seem puzzling to me, maybe from different light sources? I''d also think that the stem would be in color, too.I like the ambiguity of whether it''s the sketch coming to life, or the pencil draining color from the flower.', '2007-07-20 13:27:22.000000', NULL, 1),
(3921704, 555334, 66253, '<td valign="top">If I didn''t know it was paper, I might not guess. Eerie.</td>', 'If I didn''t know it was paper, I might not guess. Eerie.', '2007-07-20 13:27:52.000000', NULL, 1),
(3921707, 554095, 66253, '<td valign="top">puzzling</td>', 'puzzling', '2007-07-20 13:28:47.000000', NULL, 1),
(3921709, 556285, 66253, '<td valign="top">lovely simplicity</td>', 'lovely simplicity', '2007-07-20 13:29:01.000000', NULL, 1),
(3921710, 554864, 66253, '<td valign="top">Very cute!</td>', 'Very cute!', '2007-07-20 13:29:25.000000', NULL, 1),
(3921711, 554163, 57882, '<td valign="top">Quite captivating.  Difficult to recognize, but I like the abstract-ness of it.</td>', 'Quite captivating.  Difficult to recognize, but I like the abstract-ness of it.', '2007-07-20 13:29:30.000000', NULL, 1),
