(3926855, 557043, 60047, '<td valign="top">A lot of work went into this and I can almost see what the title is announcing - but the uniformity of all the other windows is somehow keeping me from seeing those fe as being curtains.</td>', 'A lot of work went into this and I can almost see what the title is announcing - but the uniformity of all the other windows is somehow keeping me from seeing those fe as being curtains.', '2007-07-22 22:45:29.000000', NULL, 1),
(3926859, 556781, 60047, '<td valign="top">I think this would have fit the title netter if the entire face had been covered. I like the strong background color.</td>', 'I think this would have fit the title netter if the entire face had been covered. I like the strong background color.', '2007-07-22 22:46:43.000000', NULL, 1),
(3926865, 556876, 60047, '<td valign="top">This is really pretty and I understand how the darkness helps the photo work - but, in a perfect world I would just like a hair more light on the origami bird.</td>', 'This is really pretty and I understand how the darkness helps the photo work - but, in a perfect world I would just like a hair more light on the origami bird.', '2007-07-22 22:49:17.000000', NULL, 1),
(3926872, 556740, 60047, '<td valign="top">With all the talk of trolls in the forums, I had to laugh when I saw this one! Great textures in the foreground.</td>', 'With all the talk of trolls in the forums, I had to laugh when I saw this one! Great textures in the foreground.', '2007-07-22 22:50:31.000000', NULL, 1),
(3926876, 556484, 60047, '<td valign="top">#2? Where is #1? (does that make me look really dumb for asking?!) I like the texture and colors here but I think it might show a bit better with a slightly higher exposure value.</td>', '#2? Where is #1? (does that make me look really dumb for asking?!) I like the texture and colors here but I think it might show a bit better with a slightly higher exposure value.', '2007-07-22 22:52:35.000000', NULL, 1),
(3926878, 556873, 60047, '<td valign="top">This is really a fascinating entry. I like the textures and the composition. Just what is this?!</td>', 'This is really a fascinating entry. I like the textures and the composition. Just what is this?!', '2007-07-22 22:53:42.000000', NULL, 1),
(3926880, 556401, 60047, '<td valign="top">Clever. Nice colors. What are you using for water?</td>', 'Clever. Nice colors. What are you using for water?', '2007-07-22 22:54:50.000000', NULL, 1),
(3926881, 556660, 60047, '<td valign="top">Great colors, focus and composition. Wonderfully pleasing and simple.</td>', 'Great colors, focus and composition. Wonderfully pleasing and simple.', '2007-07-22 22:55:52.000000', NULL, 1),
(3926953, 554286, 60047, '<td valign="top">A clever and fun way to meet the challenge!</td>', 'A clever and fun way to meet the challenge!', '2007-07-22 23:29:30.000000', NULL, 1),
(3926956, 556985, 60047, '<td valign="top">Great idea! Good composition.</td>', 'Great idea! Good composition.', '2007-07-22 23:30:29.000000', NULL, 1),
(3926970, 554157, 60047, '<td valign="top">Nice composition. I like the fact that she is walking into the light.</td>', 'Nice composition. I like the fact that she is walking into the light.', '2007-07-22 23:33:02.000000', NULL, 1),
(3926981, 557052, 60047, '<td valign="top">I think the paper shapes would stand out better with a few more shadows.</td>', 'I think the paper shapes would stand out better with a few more shadows.', '2007-07-22 23:34:59.000000', NULL, 1),
(3926989, 556948, 60047, '<td valign="top">There is a dark and morbid edge to this one. Not sure if that was intentional but it is a neat effect.</td>', 'There is a dark and morbid edge to this one. Not sure if that was intentional but it is a neat effect.', '2007-07-22 23:36:58.000000', NULL, 1),
(3926993, 555763, 60047, '<td valign="top">Very well done. I look forward to seeing how you did the transition between the real flower and the drawn one.</td>', 'Very well done. I look forward to seeing how you did the transition between the real flower and the drawn one.', '2007-07-22 23:38:27.000000', NULL, 1),
(3926996, 555404, 60047, '<td valign="top">Simple and effective.</td>', 'Simple and effective.', '2007-07-22 23:38:53.000000', NULL, 1),
(3926999, 556775, 60047, '<td valign="top">Nice tones in this B &amp; W.</td>', 'Nice tones in this B & W.', '2007-07-22 23:39:30.000000', NULL, 1),
(3927006, 554853, 60047, '<td valign="top">Perhaps you could have forgotten to sharpen? I like the high contrast but I question the shadow falling across the back of the larger bird.</td>', 'Perhaps you could have forgotten to sharpen? I like the high contrast but I question the shadow falling across the back of the larger bird.', '2007-07-22 23:41:18.000000', NULL, 1),
(3927012, 554095, 60047, '<td valign="top">Actually it looks like hair to me - but in any case it is quite stylized and artsy. I like the noise vignetting on the left side.</td>', 'Actually it looks like hair to me - but in any case it is quite stylized and artsy. I like the noise vignetting on the left side.', '2007-07-22 23:43:17.000000', NULL, 1),
(3927015, 555308, 60047, '<td valign="top">That almost looks like a face! Nice entry to the challenge.</td>', 'That almost looks like a face! Nice entry to the challenge.', '2007-07-22 23:44:01.000000', NULL, 1),
(3927021, 555209, 60047, '<td valign="top">I really like the use of the shadow rather than the real thing. It gives it an Anthony Perkins motif!(Hello, Mother).</td>', 'I really like the use of the shadow rather than the real thing. It gives it an Anthony Perkins motif!(Hello, Mother).', '2007-07-22 23:45:48.000000', NULL, 1),
(3927023, 556943, 60047, '<td valign="top">Interesting choice of colors for the planes.</td>', 'Interesting choice of colors for the planes.', '2007-07-22 23:46:14.000000', NULL, 1),
(3927026, 556746, 60047, '<td valign="top">Well done B &amp; W. Great expression in the eyes.</td>', 'Well done B & W. Great expression in the eyes.', '2007-07-22 23:46:54.000000', NULL, 1),
(3927028, 554441, 60047, '<td valign="top">I love the colors and the simplicity. Nice composition.</td>', 'I love the colors and the simplicity. Nice composition.', '2007-07-22 23:47:23.000000', NULL, 1),
(3927032, 555458, 60047, '<td valign="top">Ok, how did you get that bee to cooperate?! Beautiful flowers &amp; nice complimentary color for the plane. I wish the plane were in better focus.</td>', 'Ok, how did you get that bee to cooperate?! Beautiful flowers & nice complimentary color for the plane. I wish the plane were in better focus.', '2007-07-22 23:48:51.000000', NULL, 1),
(3927035, 555381, 60047, '<td valign="top">A fun use of desaturation.</td>', 'A fun use of desaturation.', '2007-07-22 23:49:56.000000', NULL, 1),
(3927037, 555571, 60047, '<td valign="top">Dramatic. Great composition. Great idea.</td>', 'Dramatic. Great composition. Great idea.', '2007-07-22 23:51:09.000000', NULL, 1),
(3927042, 555859, 60047, '<td valign="top">The soft focus works to take this beyond the real of photography and into the realm of art. Nice choice.</td>', 'The soft focus works to take this beyond the real of photography and into the realm of art. Nice choice.', '2007-07-22 23:52:18.000000', NULL, 1),
(3927047, 556808, 60047, '<td valign="top">Awesome. You''ve taken a common, every day thing and presented it in a wonderfully unique way. Great choice on the B &amp; W - it really helps this photo work. Great tones, DOF, lines and curves.</td>', 'Awesome. You''ve taken a common, every day thing and presented it in a wonderfully unique way. Great choice on the B & W - it really helps this photo work. Great tones, DOF, lines and curves.', '2007-07-22 23:54:24.000000', NULL, 1),
(3927051, 556549, 60047, '<td valign="top">Great idea and well executed. Beautiful color on the sea. Nice DOF.</td>', 'Great idea and well executed. Beautiful color on the sea. Nice DOF.', '2007-07-22 23:55:32.000000', NULL, 1),
(3927059, 555537, 60047, '<td valign="top">Great sense of movement here. I like that the hand is in focus and the plane''s rear end is not. How did you achieve that effect?</td>', 'Great sense of movement here. I like that the hand is in focus and the plane''s rear end is not. How did you achieve that effect?', '2007-07-22 23:57:14.000000', NULL, 1),
(3927063, 557074, 60047, '<td valign="top">Beautiful colors. Just a bit too dark on the left side. Really fascinating objects.</td>', 'Beautiful colors. Just a bit too dark on the left side. Really fascinating objects.', '2007-07-22 23:58:05.000000', NULL, 1),
(3927066, 556744, 60047, '<td valign="top">Nice definition on the toilet paper and the dog''s coat.</td>', 'Nice definition on the toilet paper and the dog''s coat.', '2007-07-22 23:58:58.000000', NULL, 1),
(3927069, 556178, 60047, '<td valign="top">Great effect, here. You''ve really made it appear to be a mountain.</td>', 'Great effect, here. You''ve really made it appear to be a mountain.', '2007-07-22 23:59:34.000000', NULL, 1),
(3927072, 553865, 60047, '<td valign="top">This one really makes me stop and think.</td>', 'This one really makes me stop and think.', '2007-07-23 00:00:33.000000', NULL, 1),
(3927080, 556779, 60047, '<td valign="top">Nice texture on the yellow fabric.</td>', 'Nice texture on the yellow fabric.', '2007-07-23 00:01:50.000000', NULL, 1),
(3927083, 554780, 60047, '<td valign="top">I guess the sign is paper? Nice B &amp; W tones. Nice composition.</td>', 'I guess the sign is paper? Nice B & W tones. Nice composition.', '2007-07-23 00:03:22.000000', NULL, 1),
(3927094, 555860, 60047, '<td valign="top">A little less contrast might have brought out more of the paper''s texture.</td>', 'A little less contrast might have brought out more of the paper''s texture.', '2007-07-23 00:05:19.000000', NULL, 1),
(3927100, 556338, 60047, '<td valign="top">Depressing but apt!</td>', 'Depressing but apt!', '2007-07-23 00:06:47.000000', NULL, 1),
(3927103, 556561, 60047, '<td valign="top">I love the color and composition. I love the way this tricks your brain.</td>', 'I love the color and composition. I love the way this tricks your brain.', '2007-07-23 00:07:47.000000', NULL, 1),
(3927106, 555334, 60047, '<td valign="top">Nicely executed. I love the low key aspect of this shot.</td>', 'Nicely executed. I love the low key aspect of this shot.', '2007-07-23 00:08:15.000000', NULL, 1),
(3927109, 557078, 60047, '<td valign="top">I was sitting here looking at this and wondering how long it took to create this paper grid. Nicely shot.</td>', 'I was sitting here looking at this and wondering how long it took to create this paper grid. Nicely shot.', '2007-07-23 00:09:43.000000', NULL, 1),
(3927127, 554439, 60047, '<td valign="top">I almost didn''t catch this. The flash reflection is just a bit distracting. I like the simplicity in the geometrical shapes.</td>', 'I almost didn''t catch this. The flash reflection is just a bit distracting. I like the simplicity in the geometrical shapes.', '2007-07-23 00:12:19.000000', NULL, 1),
(3927134, 556412, 60047, '<td valign="top">I really like the HDR effect you''ve got here. It really makes the subject pop in a cartoon-ish sort of manner.</td>', 'I really like the HDR effect you''ve got here. It really makes the subject pop in a cartoon-ish sort of manner.', '2007-07-23 00:13:26.000000', NULL, 1),
(3927143, 556724, 60047, '<td valign="top">Now - if only I could read Russian, this could serve two purposes! A fun idea.</td>', 'Now - if only I could read Russian, this could serve two purposes! A fun idea.', '2007-07-23 00:14:47.000000', NULL, 1),
(3927146, 556974, 60047, '<td valign="top">Simple, clever and done well.</td>', 'Simple, clever and done well.', '2007-07-23 00:15:43.000000', NULL, 1),
(3927152, 557033, 60047, '<td valign="top">The title doesn''t quite work for me. The subject has the appearance of a hat more than a ship (sorry).</td>', 'The title doesn''t quite work for me. The subject has the appearance of a hat more than a ship (sorry).', '2007-07-23 00:18:10.000000', NULL, 1),
(3927158, 554498, 60047, '<td valign="top">What an interesting piece. I think your choice of composition was good for this entry.</td>', 'What an interesting piece. I think your choice of composition was good for this entry.', '2007-07-23 00:20:43.000000', NULL, 1),
(3927161, 554185, 60047, '<td valign="top">Beautiful. Great colors and shapes.</td>', 'Beautiful. Great colors and shapes.', '2007-07-23 00:21:56.000000', NULL, 1),
(3927166, 555026, 60047, '<td valign="top">The colors and composition work beautifully against the white background.</td>', 'The colors and composition work beautifully against the white background.', '2007-07-23 00:22:52.000000', NULL, 1),
(3927172, 556458, 60047, '<td valign="top">I would have preferred a bit sharper focus, more DOF and a bit darker exposure value on the pages. Beautiful composition and a very apt title.</td>', 'I would have preferred a bit sharper focus, more DOF and a bit darker exposure value on the pages. Beautiful composition and a very apt title.', '2007-07-23 00:24:33.000000', NULL, 1),
(3927178, 556391, 60047, '<td valign="top">The B &amp; W really works well. I am curious as to what made you chose to center the subject rather than adhere to the rule of thirds.</td>', 'The B & W really works well. I am curious as to what made you chose to center the subject rather than adhere to the rule of thirds.', '2007-07-23 00:26:15.000000', NULL, 1),
(3927180, 556644, 60047, '<td valign="top">What a great idea. Well executed.</td>', 'What a great idea. Well executed.', '2007-07-23 00:26:55.000000', NULL, 1),
(3927189, 555158, 60047, '<td valign="top">I really like the concept behind this shot. I would like to see it a bit darker , sharper focus and greater DOF.</td>', 'I really like the concept behind this shot. I would like to see it a bit darker , sharper focus and greater DOF.', '2007-07-23 00:28:37.000000', NULL, 1),
(3927197, 556944, 43298, '<td valign="top">HAHAHAHAHAHAHAHA awesome!!!!<br/>This is so funny! Good job creating the hand, it looks great!<br/> <br/>And also a funny title. What can I say, it''s all good.</td>', 'HAHAHAHAHAHAHAHA awesome!!!!This is so funny! Good job creating the hand, it looks great! And also a funny title. What can I say, it''s all good.', '2007-07-23 00:31:35.000000', NULL, 1),
(3927200, 555771, 60047, '<td valign="top">What a great concept (very Scalvert-esque!) I think the composition is great. It might be better if you maintained more DOF (th bottom right gets pretty blurry). Also, I think it would have ben more aesthetically pleasing to bring out the red in the apple. Great title.</td>', 'What a great concept (very Scalvert-esque!) I think the composition is great. It might be better if you maintained more DOF (th bottom right gets pretty blurry). Also, I think it would have ben more aesthetically pleasing to bring out the red in the apple. Great title.', '2007-07-23 00:31:58.000000', NULL, 1),
(3927205, 556848, 60047, '<td valign="top">Not sure if it would be possible, but I wish the DOF would have allowed all papers to be in focus. Great lines in this shot.</td>', 'Not sure if it would be possible, but I wish the DOF would have allowed all papers to be in focus. Great lines in this shot.', '2007-07-23 00:33:05.000000', NULL, 1),
(3927209, 556417, 60047, '<td valign="top">This is a great Elvis. How did you do the reverse shadow in the background?</td>', 'This is a great Elvis. How did you do the reverse shadow in the background?', '2007-07-23 00:34:15.000000', NULL, 1),
(3927214, 555185, 60047, '<td valign="top">A little too blown out in the grave - but otherwise a great concept.</td>', 'A little too blown out in the grave - but otherwise a great concept.', '2007-07-23 00:35:16.000000', NULL, 1),
(3927218, 556854, 60047, '<td valign="top">Interesting desat. I think the grass blades in the foreground might be just a bit distracting.</td>', 'Interesting desat. I think the grass blades in the foreground might be just a bit distracting.', '2007-07-23 00:36:35.000000', NULL, 1),
(3927219, 554864, 60047, '<td valign="top">Cute.</td>', 'Cute.', '2007-07-23 00:36:54.000000', NULL, 1),
(3927227, 556609, 60047, '<td valign="top">This needs a better background to have them "pop." The gray is too blah and the shadows are distracting.</td>', 'This needs a better background to have them "pop." The gray is too blah and the shadows are distracting.', '2007-07-23 00:38:05.000000', NULL, 1),
(3927232, 556994, 60047, '<td valign="top">What fascinating little creatures!</td>', 'What fascinating little creatures!', '2007-07-23 00:38:58.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3927241, 556220, 60047, '<td valign="top">The blank background prevents this from being a more believable shot. How about a clock that reads 8:00am?</td>', 'The blank background prevents this from being a more believable shot. How about a clock that reads 8:00am?', '2007-07-23 00:41:02.000000', NULL, 1),
(3927246, 557066, 60047, '<td valign="top">Beautiful. The title says it all. Well done.</td>', 'Beautiful. The title says it all. Well done.', '2007-07-23 00:41:42.000000', NULL, 1),
(3927249, 554344, 60047, '<td valign="top">Goofy and fun.</td>', 'Goofy and fun.', '2007-07-23 00:42:00.000000', NULL, 1),
(3927258, 555303, 60047, '<td valign="top">I think this would be a much more fascinating shot if the line between the blue and the white were not so noticeable.</td>', 'I think this would be a much more fascinating shot if the line between the blue and the white were not so noticeable.', '2007-07-23 00:43:23.000000', NULL, 1),
(3927263, 556793, 60047, '<td valign="top">Unusual. Nice color, composition and contrast.</td>', 'Unusual. Nice color, composition and contrast.', '2007-07-23 00:44:04.000000', NULL, 1),
(3927268, 557042, 60047, '<td valign="top">OK, I got to know how you made this happen?!!</td>', 'OK, I got to know how you made this happen?!!', '2007-07-23 00:44:49.000000', NULL, 1),
(3927270, 556726, 60047, '<td valign="top">Nice lines</td>', 'Nice lines', '2007-07-23 00:45:05.000000', NULL, 1),
