(3927283, 556803, 60047, '<td valign="top">The business of the background coupled with the point of view of the camera takes a bit away from the subject.</td>', 'The business of the background coupled with the point of view of the camera takes a bit away from the subject.', '2007-07-23 00:48:26.000000', NULL, 1),
(3927291, 557077, 60047, '<td valign="top">Is the orchid in an origami box?</td>', 'Is the orchid in an origami box?', '2007-07-23 00:50:03.000000', NULL, 1),
(3927294, 556486, 60047, '<td valign="top">nice combination of body and shape.</td>', 'nice combination of body and shape.', '2007-07-23 00:50:36.000000', NULL, 1),
