(3927301, 554919, 60047, '<td valign="top">I really like the red showing up in a field of green.</td>', 'I really like the red showing up in a field of green.', '2007-07-23 00:52:29.000000', NULL, 1),
(3927304, 556954, 60047, '<td valign="top">The paper wads almost look like they''ve been drawn. Nice idea.</td>', 'The paper wads almost look like they''ve been drawn. Nice idea.', '2007-07-23 00:53:20.000000', NULL, 1),
(3927307, 556554, 60047, '<td valign="top">This really works.</td>', 'This really works.', '2007-07-23 00:53:51.000000', NULL, 1),
(3927313, 555826, 60047, '<td valign="top">Very artsy. Nice job.</td>', 'Very artsy. Nice job.', '2007-07-23 00:54:29.000000', NULL, 1),
(3927316, 556957, 60047, '<td valign="top">Focus is a little soft.</td>', 'Focus is a little soft.', '2007-07-23 00:55:11.000000', NULL, 1),
(3927320, 556460, 60047, '<td valign="top">I really love the indigo with the black.</td>', 'I really love the indigo with the black.', '2007-07-23 00:55:43.000000', NULL, 1),
