INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3932097, 556174, 80139, '<td valign="top">Ooooo... nice</td>', 'Ooooo... nice', '2007-07-24 14:08:20.000000', NULL, 1),
(3932207, 557055, 46832, '<td valign="top">That appears to have taken a lot of work.</td>', 'That appears to have taken a lot of work.', '2007-07-24 14:40:51.000000', NULL, 1),
(3932276, 555826, 52549, '<td valign="top">I love this. It''s simple, yet so beautiful.</td>', 'I love this. It''s simple, yet so beautiful.', '2007-07-24 15:11:10.000000', NULL, 1),
(3932280, 555763, 52549, '<td valign="top">This is like watching someone writing through the window of a train. Beautiful.</td>', 'This is like watching someone writing through the window of a train. Beautiful.', '2007-07-24 15:13:23.000000', NULL, 1),
(3932289, 554508, 52549, '<td valign="top">An excellently different take on the folded heart thing.</td>', 'An excellently different take on the folded heart thing.', '2007-07-24 15:15:40.000000', NULL, 1),
(3932295, 556285, 52549, '<td valign="top">This is my favourite so far. Gorgeous shot!</td>', 'This is my favourite so far. Gorgeous shot!', '2007-07-24 15:17:09.000000', NULL, 1),
(3932302, 556732, 52549, '<td valign="top">Sorry, I''m not getting this. Is the red stuff wax? or blood? Is the light a laser? Maybe cutting through the paper? Is it paper?</td>', 'Sorry, I''m not getting this. Is the red stuff wax? or blood? Is the light a laser? Maybe cutting through the paper? Is it paper?', '2007-07-24 15:19:44.000000', NULL, 1),
(3932306, 555571, 52549, '<td valign="top">Lovely. I think it may have been even better if you''d cropped it just above the blue thingy at the bottom (if you''re sitting on a 7+ score, ignore what I''ve written ;-))</td>', 'Lovely. I think it may have been even better if you''d cropped it just above the blue thingy at the bottom (if you''re sitting on a 7+ score, ignore what I''ve written ;-))', '2007-07-24 15:21:57.000000', NULL, 1),
(3932307, 556412, 52549, '<td valign="top">How cool is this? Great idea.</td>', 'How cool is this? Great idea.', '2007-07-24 15:22:21.000000', NULL, 1),
(3932312, 554344, 52549, '<td valign="top">Hehe ;-) I''ll give you an extra point for originality (and for making me smile).</td>', 'Hehe ;-) I''ll give you an extra point for originality (and for making me smile).', '2007-07-24 15:24:05.000000', NULL, 1),
(3932315, 556385, 52549, '<td valign="top">Gorgeous lighting and shapes.</td>', 'Gorgeous lighting and shapes.', '2007-07-24 15:24:37.000000', NULL, 1),
(3932320, 554864, 58452, '<td valign="top">Nice pure tones of blue, a superb graphic image. Methinks I detect the  presence of DeSousa here.  Maybe.  Excellent.  Should ribbon.</td>', 'Nice pure tones of blue, a superb graphic image. Methinks I detect the  presence of DeSousa here.  Maybe.  Excellent.  Should ribbon.', '2007-07-24 15:25:32.000000', NULL, 1),
(3932322, 556527, 52549, '<td valign="top">Beautiful, just beautiful!</td>', 'Beautiful, just beautiful!', '2007-07-24 15:26:33.000000', NULL, 1),
(3932325, 554163, 58452, '<td valign="top">I can''t put my finger on why I like this image.  The shapes, forms and shading just captivate my minds eye.  There''s something almost pornographic...    LOL.   Excellent image, should easily top ten.</td>', 'I can''t put my finger on why I like this image.  The shapes, forms and shading just captivate my minds eye.  There''s something almost pornographic...    LOL.   Excellent image, should easily top ten.', '2007-07-24 15:27:20.000000', NULL, 1),
(3932329, 556616, 58452, '<td valign="top">Interesting multiple faces and interchangeable genders from side to side.  Maybe to abstract for the voters, but I like it plenty.  Excellent.</td>', 'Interesting multiple faces and interchangeable genders from side to side.  Maybe to abstract for the voters, but I like it plenty.  Excellent.', '2007-07-24 15:29:10.000000', NULL, 1),
(3932337, 556174, 58452, '<td valign="top">I seldom comment on frames but I believe this one really helps you image. I can never figure out how these impossible images are constructed.  My only nit, the seam in the bottom left of the figure.  If you can make the impossible figure, you could certainly eliminate this seam.  ;)  The tiny white line to the left of the thumb draws the eye but doesn''t detract much.  All in all, I love it and it will probably ribbon.</td>', 'I seldom comment on frames but I believe this one really helps you image. I can never figure out how these impossible images are constructed.  My only nit, the seam in the bottom left of the figure.  If you can make the impossible figure, you could certainly eliminate this seam.  ;)  The tiny white line to the left of the thumb draws the eye but doesn''t detract much.  All in all, I love it and it will probably ribbon.', '2007-07-24 15:32:00.000000', NULL, 1),
(3932339, 557066, 58452, '<td valign="top">Beautiful colors, lines, shapes and forms.<br/>Should to ten.</td>', 'Beautiful colors, lines, shapes and forms.Should to ten.', '2007-07-24 15:33:19.000000', NULL, 1),
(3932341, 555334, 58452, '<td valign="top">Beautiful symmetry, and almost flame like effect, very nice.</td>', 'Beautiful symmetry, and almost flame like effect, very nice.', '2007-07-24 15:34:33.000000', NULL, 1),
(3932348, 554286, 58452, '<td valign="top">Funny.  Wonder if the lady "baghead" voters look like this? Must be SC with the paper crown.  heheheh  Love it.</td>', 'Funny.  Wonder if the lady "baghead" voters look like this? Must be SC with the paper crown.  heheheh  Love it.', '2007-07-24 15:36:43.000000', NULL, 1),
(3932357, 556412, 58452, '<td valign="top">Of the several images like this in the challenge, this one takes the cake.  Those eyes!  Looks a little like Stu Davidson.  Probably not.<br/>heheheheh Nice concept.</td>', 'Of the several images like this in the challenge, this one takes the cake.  Those eyes!  Looks a little like Stu Davidson.  Probably not.heheheheh Nice concept.', '2007-07-24 15:40:13.000000', NULL, 1),
(3932362, 555303, 58452, '<td valign="top">Neat graphic concept!  Love the shadow on the bottom.  Since this is advanced editing the dust spot in the upper right should have been cloned. and the shadow/paper cut/tear thing going on at the right hand horizon should have been fixed.  Still a very nice image.</td>', 'Neat graphic concept!  Love the shadow on the bottom.  Since this is advanced editing the dust spot in the upper right should have been cloned. and the shadow/paper cut/tear thing going on at the right hand horizon should have been fixed.  Still a very nice image.', '2007-07-24 15:42:36.000000', NULL, 1),
(3932366, 556527, 58452, '<td valign="top">Nice black and white.  I wish the page top hadn''t interfaced with the child''s mouth.<br/>Still a very strong image, almost like something Goodman would do.  Very nice.</td>', 'Nice black and white.  I wish the page top hadn''t interfaced with the child''s mouth.Still a very strong image, almost like something Goodman would do.  Very nice.', '2007-07-24 15:44:28.000000', NULL, 1),
(3932369, 555826, 58452, '<td valign="top">The abstract really draw my eye.  Top left just a tad too hot for me, but that''s just a nit pick.  Lovely image.</td>', 'The abstract really draw my eye.  Top left just a tad too hot for me, but that''s just a nit pick.  Lovely image.', '2007-07-24 15:45:17.000000', NULL, 1),
(3932370, 556616, 75898, '<td valign="top">I''m still trying to wrap my head around this one.  Nicely executed.</td>', 'I''m still trying to wrap my head around this one.  Nicely executed.', '2007-07-24 15:45:43.000000', NULL, 1),
(3932381, 554185, 58452, '<td valign="top">This image has the damnest effect on my vision.  Parts of it look blurred and then move about as I gaze at it.  Weird.  Wonder how you achieved this.... or maybe I''m getting cataracts!  heheheh  Doesn''t look precisely centered which I suspect you wanted????  Maybe a version without the frame would have allow the figure to be larger and have greater affect.  Anyway this is very good!  Bumping it a point as I comment.</td>', 'This image has the damnest effect on my vision.  Parts of it look blurred and then move about as I gaze at it.  Weird.  Wonder how you achieved this.... or maybe I''m getting cataracts!  heheheh  Doesn''t look precisely centered which I suspect you wanted????  Maybe a version without the frame would have allow the figure to be larger and have greater affect.  Anyway this is very good!  Bumping it a point as I comment.', '2007-07-24 15:49:50.000000', NULL, 1),
(3932385, 557036, 58452, '<td valign="top">Hope you got that stack put out!!!  Neat green flames.</td>', 'Hope you got that stack put out!!!  Neat green flames.', '2007-07-24 15:53:03.000000', NULL, 1),
(3932388, 557074, 58452, '<td valign="top">Love the range of tones in the colors caused by the diagonal to your light source.  That and the interesting way the subject interfaces with it''s background/foreground. <br/>The bottom right of the yellow box, is just a bit hot for my tastes, but that''s just a nit pick.  I like it.</td>', 'Love the range of tones in the colors caused by the diagonal to your light source.  That and the interesting way the subject interfaces with it''s background/foreground. The bottom right of the yellow box, is just a bit hot for my tastes, but that''s just a nit pick.  I like it.', '2007-07-24 15:55:58.000000', NULL, 1),
(3932398, 555771, 58452, '<td valign="top">Hehehehehe, neat concept.</td>', 'Hehehehehe, neat concept.', '2007-07-24 16:02:40.000000', NULL, 1),
(3932406, 556943, 58452, '<td valign="top">Don''t know whether it is the lighting or placement of the aircraft in the frame, but it just doesn''t clik with the title for me.  I do like the colors of the aircraft.</td>', 'Don''t know whether it is the lighting or placement of the aircraft in the frame, but it just doesn''t clik with the title for me.  I do like the colors of the aircraft.', '2007-07-24 16:05:24.000000', NULL, 1),
(3932412, 557075, 58452, '<td valign="top">Interesting concept.  The super blown-out spot in the top center by the subjects left forearm really grabs the eye and detracts.</td>', 'Interesting concept.  The super blown-out spot in the top center by the subjects left forearm really grabs the eye and detracts.', '2007-07-24 16:07:36.000000', NULL, 1),
(3932414, 557079, 58452, '<td valign="top">Unique concept.  The blown spots in the foliage kept me from seeing the dollar butterfly.  Some people don''t look several seconds.....</td>', 'Unique concept.  The blown spots in the foliage kept me from seeing the dollar butterfly.  Some people don''t look several seconds.....', '2007-07-24 16:10:17.000000', NULL, 1),
(3932418, 555385, 58452, '<td valign="top">Interesting swirl of flame colors.  I wonder if this was a long exposure tech.  The center of the swirl is far to hot for my tastes.</td>', 'Interesting swirl of flame colors.  I wonder if this was a long exposure tech.  The center of the swirl is far to hot for my tastes.', '2007-07-24 16:11:59.000000', NULL, 1),
(3932419, 554123, 75898, '<td valign="top">What a beautiful view!  I think removing the water droplets on the window, taking away the belt-thing(?) and little round thing on the table and hiding the power cord would''ve taken away some minor distractions.  Nevertheless, a nicely lit and well composed shot.</td>', 'What a beautiful view!  I think removing the water droplets on the window, taking away the belt-thing(?) and little round thing on the table and hiding the power cord would''ve taken away some minor distractions.  Nevertheless, a nicely lit and well composed shot.', '2007-07-24 16:12:25.000000', NULL, 1),
(3932420, 555020, 75898, '<td valign="top">I hope this was taken at a paper museum.  Otherwise, you''ve got way too much time (and talent) on your hands.</td>', 'I hope this was taken at a paper museum.  Otherwise, you''ve got way too much time (and talent) on your hands.', '2007-07-24 16:12:58.000000', NULL, 1),
